 let cards=[],n=0;
 const pending=(s.alerts||[]).find(x=>x.k==='Pending orders'),unverified=(s.alerts||[]).find(x=>x.k==='Unverified');
 if(finite(pending&&pending.v)>0||finite(unverified&&unverified.v)>0){
 const p=finite(pending&&pending.v),u=finite(unverified&&unverified.v);
 cards.push(card('0'+(++n),'signal','Clear friction before chasing more demand.',(p!==null?SV(String(p))+' pending orders':'Pending count unknown')+(u!==null?' · '+SV(String(u))+' unverified':'')+' at the online dashboard read.', 'These are separate dashboard categories, not a combined backlog. Counts do not identify the cause, current delay or lost revenue.', 'Review the oldest available orders and check verification blockers. Confirm current status before contacting customers or changing dispatch priorities.',esc(stamp('Online dashboard',onlineAt)),action('Review orders','orders')));
 }
 const pb=Array.isArray(R.pendingBills)?R.pendingBills:[],pr=(R.products||[]).filter(p=>finite(p.pendingUnits)>0);
 if(pb.length||pr.length){cards.push(card('0'+(++n),'signal','Keep unposted sales out of decisions.',SV(esc(pb.join(', ')||'Retail bill amounts'))+' still has pending product amounts in this report.', 'A blank line amount is unknown, not a free item. Posted product totals do not include those unknown amounts, so revenue rankings can move after posting.', 'Check the bill in the normal accounting workflow, then revisit product ranking after the next source read. Do not estimate missing SKU revenue.',esc(stamp('Retail product sales',retailAt)),action('Review sellers','best')))}
 const products=topRetailGroups(Array.isArray(R.products)?R.products:[]).filter(p=>finite(p.units)>0&&!/custom charges/i.test(p.name||p.key||'')).sort((a,b)=>Number(b.units)-Number(a.units)||String(a.name||a.key).localeCompare(String(b.name||b.key)));
 const lead=products[0];if(lead&&T.date===IST()){
 const ties=products.filter(p=>Number(p.units)===Number(lead.units)).length;
 cards.push(card('0'+(++n),'idea','Give proven interest a better storefront.',SV(esc(lead.name||lead.key))+' has '+SV(String(lead.units))+' units in the supplied retail product read'+(ties>1?' (tied for the highest units shown).':'.'), 'This is a same-day merchandising lead, not evidence of an online bestseller or a lasting trend. Retail coverage may be incomplete; one day cannot prove repeat demand.', 'Audit this style\'s photos, fit details and available sizes. Consider a small no-discount placement test only after checking stock. Judge it on a comparable period, not the retail total alone.',esc(stamp('Retail product sales',retailAt))+' · '+esc(T.date)+' · '+(R.complete===true?'full coverage reported':'coverage not confirmed'),action('See the product evidence','best')))
 }
 const stockRows=Array.isArray(data.retailStock)?data.retailStock:[],stockMap=new Map();stockRows.forEach(z=>{const k=String(z.sku||'');stockMap.set(k,stockMap.has(k)?null:z)});
 let candidates=[];if(T.date===IST()&&fresh(retailAt)&&fresh(stockAt)){for(const p of R.products||[])for(const z of p.skus||[]){const q=stockMap.get(String(z.sku||'')),u=finite(z.units),left=q&&finite(q.onHand);if(q&&u>0&&left!==null&&left<=3&&!/custom charges/i.test(z.sku||''))candidates.push({sku:z.sku,units:u,left});}candidates.sort((a,b)=>a.left-b.left||b.units-a.units);}
 const c=candidates.slice(0,3);
 cards.push(card('0'+(++n),'stock',c.length?'Check these sold, low-stock sizes.':'No blind restock calls.',c.length?c.map(z=>SV(esc(z.sku))+' · '+SV(String(z.units))+' sold / '+SV(String(z.left))+' on hand').join('<br>'):'A restock shortlist needs fresh sales, fresh stock and exact SKU matches. Those checks are not all available right now.', 'Retail sales and retail stock are separate reads. This is a check list, not a purchase quantity: supplier lead time, reservations, returns, margin and repeated demand are not all known.', c.length?'Confirm current available-to-sell stock and repeat demand for these exact sizes before choosing a transfer or reorder. No purchases are placed.':'Refresh the normal source workflow first. Missing or old rows are never treated as zero. Online stock is not substituted for retail stock.',esc(stamp('Retail product sales',retailAt))+'<br>'+esc(stamp('Retail stock',stockAt)),action('Inspect stock','stock')));
 const channels=Object.entries(s.ch||{}).filter(([k,v])=>v&&finite(v.amt)!==null&&finite(v.n)>0).sort((a,b)=>b[1].amt-a[1].amt);
 if(channels.length>1){cards.push(card('0'+(++n),'idea','Choose a channel question, not a budget guess.',channels.slice(0,2).map(([k,v])=>esc(k)+': '+SV(inr(v.amt))+' / '+SV(String(v.n))+' orders').join('<br>'), 'Recorded channel sales are not profit or return on ad spend. Marketing cost, returns, fees and conversion rates are not in this read.', 'Compare the same style\'s listing quality and size availability across these channels. Investigate differences before changing ad spend or discounting.',esc(stamp('Online dashboard',onlineAt)),action('Review channel details','today')))}
 const publicCards=[
 {title:'Make the winning style easier to judge.',text:'Google\'s apparel guidance recommends clear variant details, high-quality images and additional angles. For Dressjet, audit fit, fabric and colour consistency on a style with verified recent interest before making more creative.',next:'Check three product pages. Is the size/colour in the title, image and selected variant consistent? This is a proposed audit, not a detected listing defect.',url:'https://support.google.com/merchants/answer/7348545?hl=en',name:'Google Merchant Center · apparel guidance'},
 {title:'Test a useful add-on, not a blanket discount.',text:'Shopify supports complementary and related product recommendations on compatible themes. A sensible Dressjet experiment is one relevant, in-stock pairing on a product page, without assuming customers already buy the pair together.',next:'Check the store theme and actual stock first. Measure attach rate and margin over a comparable period. No feature availability or sales lift has been verified for this store.',url:'https://help.shopify.com/en/manual/online-store/search-and-discovery/product-recommendations',name:'Shopify Help · product recommendations'},
 {title:'Treat an occasion story as a hypothesis.',text:'A wedding-guest or festive edit could be tested using existing products and photography. No live fashion trend or seasonal demand increase is claimed here. Google notes that Trends measures relative search interest, not sales demand.',next:'Before committing a campaign, compare relevant India search topics over the same period, then check store enquiries and sell-through. No Trends series has been read for this page.',url:'https://support.google.com/trends/answer/4365533',name:'Google Trends · interpreting search interest'}
 ];
 return '<section class="hi-intro"><span class="hi-overline">DRESSJET / INSIGHTS</span><h2>Your next good move<span>.</span></h2><p>What the numbers suggest.<br>What is worth testing next.</p><div class="hi-method"><span>Measured signals</span><span>Ideas, not predictions</span></div></section><nav class="hi-jump" aria-label="Insight categories"><a href="#hi-business">Your business ↓</a><a href="#hi-public">Public playbook ↓</a></nav><section id="hi-business"><div class="hi-section-title"><small>01 / FROM YOUR DATA</small><h2>Notice. Then act.</h2><p>Each read keeps its own time. Old signals are not live priorities.</p></div>'+cards.join('')+'</section><section id="hi-public"><div class="hi-section-title"><small>02 / PUBLIC PLAYBOOK</small><h2>A little outside perspective.</h2><p>Primary guidance checked 16 Oct 2026. Evergreen ideas, not a live trends feed.</p></div>'+publicCards.map((p,i)=>'<article class="hi-public-card"><span class="hi-overline">0'+(i+1)+' / GUIDANCE + DRESSJET IDEA</span><h2>'+p.title+'</h2><p>'+p.text+'</p><details><summary>A small test <b>+</b></summary><p>'+p.next+'</p></details><a href="'+p.url+'" target="_blank" rel="noopener noreferrer">'+p.name+' ↗</a><small>Guidance checked 16 Oct 2026</small></article>').join('')+'</section><p class="hi-disclaimer">Suggested actions only. No orders, messages, purchases or campaigns are started here. Refresh the source evidence before acting. Swipe right or use Back to return.</p>';
