function chanOf(s,I){if(!(s.ch&&typeof s.ch==='object')&&I.ct&&Array.isArray(I.ct.by)&&I.ct.by.length){const m={};I.ct.by.forEach(x=>{m[x.ch]={amt:nn(x.rev),n:nn(x.orders)}});return {m,full:true};}const T=[s.ch,s.chTotals,s.channelTotals,s.byChannel].find(x=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).length);if(T)return {m:T,full:true};const m={};I.live.forEach(o=>m[o.ch]=(m[o.ch]||0)+nn(o.amt));if(I.partial&&I.gap>0)m['Not itemised']=I.gap;return {m,full:false};}
