function onStockRows(){const st=A(data.stock);if(!st)return null;const per={};((data.sellers&&data.sellers.week)||[]).forEach(x=>{if(x.qty)per[x.sku]=x.qty/7});return st.map(x=>{const pd=x.perDay!=null?x.perDay:(per[x.sku]||0);return {sku:String(x.sku),name:x.name||'',onHand:nn(x.onHand),pd,days:pd>0?nn(x.onHand)/pd:null,ch:'Online'}});}
